   134	bool HeifPixelImage::add_plane(heif_channel channel, int width, int height, int bit_depth)
   135	{
   136	  assert(width >= 0);
   137	  assert(height >= 0);
   138	  assert(bit_depth >= 1);
   139	
   140	  // use 16 byte alignment
   141	  int alignment = 16; // must be power of two
   142	
   143	  ImagePlane plane;
   144	  plane.width = width;
   145	  plane.height = height;
   146	
   147	
   148	  // for backwards compatibility, allow for 24/32 bits for RGB/RGBA interleaved chromas
   149	
   150	  if (m_chroma == heif_chroma_interleaved_RGB && bit_depth==24) {
   151	    bit_depth = 8;
   152	  }
   153	
   154	  if (m_chroma == heif_chroma_interleaved_RGBA && bit_depth==32) {
   155	    bit_depth = 8;
   156	  }
   157	
   158	  plane.bit_depth = bit_depth;
   159	
   160	
   161	  int bytes_per_component = (bit_depth+7)/8;
   162	  int bytes_per_pixel = num_interleaved_pixels_per_plane(m_chroma) * bytes_per_component;
   163	
   164	  plane.stride = width * bytes_per_pixel;
   165	  plane.stride = (plane.stride+alignment-1) & ~(alignment-1);
   166	
   167	  try {
   168	    plane.allocated_mem = new uint8_t[height * plane.stride + alignment-1];
   169	    plane.mem = plane.allocated_mem;
   170	
   171	    // shift beginning of image data to aligned memory position
   172	
   173	    auto mem_start_addr = (uint64_t)plane.mem;
   174	    auto mem_start_offset = (mem_start_addr & (alignment-1));
   175	    if (mem_start_offset != 0) {
   176	      plane.mem += alignment - mem_start_offset;
   177	    }
   178	
   179	    m_planes.insert(std::make_pair(channel, std::move(plane)));
   180	  }
   181	  catch (const std::bad_alloc& excpt) {
   182	    return false;
   183	  }
   184	
   185	  return true;
   186	}
