   620	Error HeifPixelImage::fill_RGB_16bit(uint16_t r, uint16_t g, uint16_t b, uint16_t a)
   621	{
   622	  for (const auto& channel : { heif_channel_R, heif_channel_G, heif_channel_B, heif_channel_Alpha } ) {
   623	
   624	    const auto plane_iter = m_planes.find(channel);
   625	    if (plane_iter == m_planes.end()) {
   626	
   627	      // alpha channel is optional, R,G,B is required
   628	      if (channel == heif_channel_Alpha) {
   629	        continue;
   630	      }
   631	
   632	      return Error(heif_error_Usage_error,
   633	                   heif_suberror_Nonexisting_image_channel_referenced);
   634	
   635	    }
   636	
   637	    ImagePlane& plane = plane_iter->second;
   638	
   639	    if (plane.bit_depth != 8) {
   640	      return Error(heif_error_Unsupported_feature,
   641	                   heif_suberror_Unspecified,
   642	                   "Can currently only fill images with 8 bits per pixel");
   643	    }
   644	
   645	    int h = plane.height;
   646	
   647	    int stride = plane.stride;
   648	    uint8_t* data = plane.mem;
   649	
   650	    uint16_t val16;
   651	    switch (channel) {
   652	    case heif_channel_R: val16=r; break;
   653	    case heif_channel_G: val16=g; break;
   654	    case heif_channel_B: val16=b; break;
   655	    case heif_channel_Alpha: val16=a; break;
   656	    default:
   657	      // initialization only to avoid warning of uninitalized variable.
   658	      val16 = 0;
   659	      // Should already be detected by the check above ("m_planes.find").
   660	      assert(false);
   661	    }
   662	
   663	    uint8_t val8 = static_cast<uint8_t>(val16>>8);
   664	
   665	    memset(data, val8, stride*h);
   666	  }
   667	
   668	  return Error::Ok;
   669	}
